# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(sift(emit(gather(shape(render(raw))))))

